"""Typed native-effect dependency audit, using generated bytes, not game assets.

Synthetic payload hashes are deliberately refreshed for semantic corruptions:
those cases must reach the parser/dependency checks rather than fail the hash
gate. The optional extraction test reads local game resources without copying
them into this repository. Neither path establishes rendered appearance.
"""

import copy
import hashlib
import os
from pathlib import Path
import struct
import sys
import tempfile
import unittest


TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
import check_crystal_flame_native_effect as contract


# Known resource-type IDs; the fixture constructor does not call the checker.
TYPE_IDS = {
    "particles": 0xA8193123526FAD64,
    "material": 0xEAC0B497876ADEDF,
    "texture": 0xCD4238C6A0C69E32,
}
RESOURCE_IDS = {
    "effect": 0x3DB3CE6438D57683,
    "child_material": 0xA0EC15D2679F209F,
    "parent_material": 0xEF52A5800BEB269E,
    "texture": 0x73548ADEE6C02173,
}
TRAILER = bytes(range(41))
CLOUD_BASE = 40
INITIALIZER_SIZES = {0: 12, 1: 16, 6: 8, 11: 44}


def package_payload(entries):
    return struct.pack("<I", len(entries)) + b"".join(
        struct.pack("<QQ", *entry) for entry in entries
    ) + TRAILER


def material_payload(parent, textures=()):
    """Generate only the public v43 binding-table layout and zero padding."""
    payload = bytearray(max(40, 28 + 12 * len(textures)))
    struct.pack_into("<IIIIQI", payload, 0, 43, 1, 12, 0, parent, len(textures))
    for index, (channel, resource) in enumerate(textures):
        struct.pack_into("<IQ", payload, 28 + 12 * index, channel, resource)
    return bytes(payload)


def particle_payload(expected):
    """Make one structurally valid cloud, with no native opaque data."""
    cloud = expected["cloud"]
    payload = bytearray(CLOUD_BASE + cloud["total_size"])
    struct.pack_into("<I", payload, 0, expected["version"])
    struct.pack_into("<I", payload, 0x24, expected["cloud_count"])
    fields = {
        4: cloud["capacity"],
        0xAC: len(cloud["initializer_types"]),
        0xB0: cloud["initializer_offset"],
        0xB4: len(cloud["simulator_types"]),
        0xB8: cloud["simulator_offset"],
        0xBC: cloud["renderer_offset"],
        0xC4: cloud["visualizer_count"],
        0xC8: cloud["visualizer_offset"],
        0xCC: cloud["total_size"],
    }
    for offset, value in fields.items():
        struct.pack_into("<I", payload, CLOUD_BASE + offset, value)
    cursor = CLOUD_BASE + cloud["initializer_offset"]
    for kind in cloud["initializer_types"]:
        struct.pack_into("<I", payload, cursor, kind)
        cursor += INITIALIZER_SIZES[kind]
    cursor = CLOUD_BASE + cloud["simulator_offset"]
    for kind in cloud["simulator_types"]:
        struct.pack_into("<BI", payload, cursor, kind, 0)
        cursor += 5
    visualizer = CLOUD_BASE + cloud["visualizer_offset"]
    struct.pack_into("<I", payload, visualizer, cloud["visualizer_type"])
    struct.pack_into(
        "<Q", payload, visualizer + cloud["material_offset_from_visualizer"],
        int(cloud["material_id"], 16),
    )
    return bytes(payload)


class SyntheticNativeEffectContract(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.fixture = copy.deepcopy(contract.load_fixture())
        self.entries = [
            (TYPE_IDS[spec["type"]], int(spec["id"], 16))
            for spec in self.fixture["resources"].values()
        ]
        # Preserve the observed table cardinality without reproducing its data.
        self.entries += [(0x101, 0x10000 + index) for index in range(483)]
        self.write_package(package_payload(self.entries))
        self.write_resource("effect", particle_payload(self.fixture["particle"]))
        self.write_resource("child_material", material_payload(
            RESOURCE_IDS["parent_material"], [(0x9CA38F7D, RESOURCE_IDS["texture"])]
        ))
        self.write_resource("parent_material", material_payload(0))
        self.write_resource("texture", b"synthetic texture bytes; never rendered")

    def path_for(self, name):
        return self.root / self.fixture["resources"][name]["path"]

    def write_pinned(self, specification, payload):
        path = self.root / specification["path"]
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(payload)
        specification["size"] = len(payload)
        specification["sha256"] = hashlib.sha256(payload).hexdigest()

    def write_package(self, payload):
        self.write_pinned(self.fixture["package"], payload)

    def write_resource(self, name, payload):
        self.write_pinned(self.fixture["resources"][name], payload)

    def assert_rejected(self):
        with self.assertRaises(ValueError):
            contract.audit(self.root, self.fixture)

    def test_generated_dependency_chain_passes_without_claiming_runtime(self):
        report = contract.audit(self.root, self.fixture)
        self.assertEqual(report["status"], "native-effect-direct-dependencies-verified")
        self.assertIs(report["runtime_verified"], False)
        self.assertIs(report["color_verified"], False)
        self.assertIs(report["rendered_size_verified"], False)

    def test_all_four_resources_are_required_as_typed_members(self):
        members = contract.require_members(
            (self.root / self.fixture["package"]["path"]).read_bytes(), self.fixture
        )
        self.assertEqual(set(members), set(self.entries))

    def test_missing_required_member_rejected_after_repinning_package(self):
        original = self.entries.copy()
        for index in range(4):
            with self.subTest(resource=index):
                entries = original.copy()
                entries[index] = (0x101, 0x20000 + index)
                self.write_package(package_payload(entries))
                self.assert_rejected()

    def test_same_id_under_wrong_resource_type_is_not_membership(self):
        original = self.entries.copy()
        for index in range(4):
            with self.subTest(resource=index):
                entries = original.copy()
                entries[index] = (0x101, entries[index][1])
                self.write_package(package_payload(entries))
                self.assert_rejected()

    def test_duplicate_required_or_unrelated_table_member_rejected(self):
        for duplicate_index in (0, 4):
            with self.subTest(duplicate_index=duplicate_index):
                entries = self.entries.copy()
                entries[-1] = entries[duplicate_index]
                self.write_package(package_payload(entries))
                self.assert_rejected()

    def test_required_pair_in_trailer_cannot_replace_missing_table_entry(self):
        entries = self.entries.copy()
        missing_pair = entries[0]
        entries[0] = (0x101, 0x20000)
        payload = bytearray(package_payload(entries))
        payload[-41:-25] = struct.pack("<QQ", *missing_pair)
        self.write_package(payload)
        self.assert_rejected()

    def test_truncated_package_table_rejected_with_fresh_hash(self):
        self.write_package(package_payload(self.entries)[:4 + 16 * 486])
        self.assert_rejected()

    def test_package_header_count_cannot_hide_extra_entries(self):
        payload = bytearray(package_payload(self.entries))
        struct.pack_into("<I", payload, 0, 486)
        self.write_package(payload)
        self.assert_rejected()

    def test_package_trailing_bytes_rejected_with_fresh_hash(self):
        self.write_package(package_payload(self.entries) + b"unexpected")
        self.assert_rejected()

    def test_missing_package_or_resource_file_rejected(self):
        paths = [self.root / self.fixture["package"]["path"]]
        paths += [self.path_for(name) for name in self.fixture["resources"]]
        for path in paths:
            with self.subTest(path=path.name):
                payload = path.read_bytes()
                path.unlink()
                self.assert_rejected()
                path.write_bytes(payload)

    def test_same_length_hash_corruption_rejected_for_each_payload(self):
        paths = [self.root / self.fixture["package"]["path"]]
        paths += [self.path_for(name) for name in self.fixture["resources"]]
        for path in paths:
            with self.subTest(path=path.name):
                original = path.read_bytes()
                changed = bytearray(original)
                changed[-1] ^= 1
                path.write_bytes(changed)
                self.assert_rejected()
                path.write_bytes(original)

    def test_size_corruption_rejected_for_each_payload(self):
        paths = [self.root / self.fixture["package"]["path"]]
        paths += [self.path_for(name) for name in self.fixture["resources"]]
        for path in paths:
            with self.subTest(path=path.name):
                original = path.read_bytes()
                path.write_bytes(original + b"\x00")
                self.assert_rejected()
                path.write_bytes(original)

    def test_wrong_child_parent_rejected_even_with_fresh_material_hash(self):
        self.write_resource("child_material", material_payload(
            RESOURCE_IDS["parent_material"] ^ 1, [(0x9CA38F7D, RESOURCE_IDS["texture"])]
        ))
        self.assert_rejected()

    def test_wrong_child_texture_rejected_even_with_fresh_material_hash(self):
        self.write_resource("child_material", material_payload(
            RESOURCE_IDS["parent_material"], [(0x9CA38F7D, RESOURCE_IDS["texture"] ^ 1)]
        ))
        self.assert_rejected()

    def test_wrong_texture_channel_rejected(self):
        self.write_resource("child_material", material_payload(
            RESOURCE_IDS["parent_material"], [(0x9CA38F7C, RESOURCE_IDS["texture"])]
        ))
        self.assert_rejected()

    def test_missing_child_texture_binding_rejected(self):
        self.write_resource("child_material", material_payload(RESOURCE_IDS["parent_material"]))
        self.assert_rejected()

    def test_unexpected_parent_texture_dependency_rejected(self):
        self.write_resource("parent_material", material_payload(0, [(0x12, RESOURCE_IDS["texture"])]))
        self.assert_rejected()

    def test_nonzero_parent_parent_id_rejected(self):
        self.write_resource("parent_material", material_payload(0x1234))
        self.assert_rejected()

    def test_duplicate_material_texture_channel_rejected(self):
        self.write_resource("child_material", material_payload(
            RESOURCE_IDS["parent_material"], [(0x9CA38F7D, RESOURCE_IDS["texture"])] * 2
        ))
        self.assert_rejected()

    def test_malformed_material_headers_and_texture_bounds_rejected(self):
        original = self.path_for("child_material").read_bytes()
        for offset, value in ((0, 42), (4, 0), (8, 0xFFFF), (24, 0xFFFF)):
            with self.subTest(offset=offset):
                changed = bytearray(original)
                struct.pack_into("<I", changed, offset, value)
                self.write_resource("child_material", changed)
                self.assert_rejected()

    def test_particle_header_and_cloud_contract_changes_rejected(self):
        original = self.path_for("effect").read_bytes()
        mutations = {
            "version": (0, 67), "cloud_count": (0x24, 2),
            "capacity": (CLOUD_BASE + 4, 41),
            "initializer_count": (CLOUD_BASE + 0xAC, 8),
            "initializer_offset": (CLOUD_BASE + 0xB0, 207),
            "simulator_count": (CLOUD_BASE + 0xB4, 6),
            "simulator_offset": (CLOUD_BASE + 0xB8, 337),
            "renderer_offset": (CLOUD_BASE + 0xBC, 362),
            "visualizer_count": (CLOUD_BASE + 0xC4, 2),
            "visualizer_offset": (CLOUD_BASE + 0xC8, 514),
            "total_size": (CLOUD_BASE + 0xCC, 1214),
        }
        for name, (offset, value) in mutations.items():
            with self.subTest(field=name):
                changed = bytearray(original)
                struct.pack_into("<I", changed, offset, value)
                self.write_resource("effect", changed)
                self.assert_rejected()

    def test_particle_component_types_rejected_with_fresh_hash(self):
        original = self.path_for("effect").read_bytes()
        for offset, packing in ((CLOUD_BASE + 208, "<I"), (CLOUD_BASE + 336, "<B"),
                                (CLOUD_BASE + 513, "<I")):
            with self.subTest(offset=offset):
                changed = bytearray(original)
                struct.pack_into(packing, changed, offset, 255)
                self.write_resource("effect", changed)
                self.assert_rejected()

    def test_particle_wrong_material_cannot_reuse_valid_package(self):
        changed = bytearray(self.path_for("effect").read_bytes())
        struct.pack_into("<Q", changed, CLOUD_BASE + 513 + 12, RESOURCE_IDS["child_material"] ^ 1)
        self.write_resource("effect", changed)
        self.assert_rejected()

    def test_truncated_and_trailing_particle_bytes_rejected_with_fresh_hash(self):
        original = self.path_for("effect").read_bytes()
        for changed in (original[:39], original[:200], original[:-1], original + b"\x00"):
            with self.subTest(size=len(changed)):
                self.write_resource("effect", changed)
                self.assert_rejected()


class OptionalLocalExtraction(unittest.TestCase):
    def test_native_extracted_resources_match_pins_without_visual_claims(self):
        configured = os.environ.get("WARLOCK_EXTRACTED_GAME_ROOT")
        root = Path(configured) if configured else Path(
            "D:/Game Mods/Vermintide 2 modding/VT2 Bundle Extract"
        )
        if not root.is_dir():
            if configured:
                self.fail("WARLOCK_EXTRACTED_GAME_ROOT does not identify an existing directory")
            self.skipTest("No local native extraction; synthetic coverage remains active")
        report = contract.audit(root, contract.load_fixture())
        self.assertEqual(report["status"], "native-effect-direct-dependencies-verified")
        for field in ("runtime_verified", "color_verified", "rendered_size_verified"):
            self.assertIs(report[field], False)


if __name__ == "__main__":
    unittest.main()
